    ["config.core.description.catch_fresh_fish_along_the_northern_coastline_and_pontoon_then_s.9ba1254c"] = "Prinde pește proaspăt de-a lungul coastei de nord și a pontonului, apoi vinde-l la magazinele locale.",
    ["config.core.description.collect_bins_on_city_routes_and_unload_at_the_depot.6c25ec60"] = "Colectați pubelele de pe rutele urbane și descărcați-le la depou.",
    ["config.core.description.collect_waste_routes_across_city_neighborhoods_and_unload_at_the.1d211277"] = "Colectați deșeurile din cartierele orașului și descărcați-le la depozitul central de compactare.",
    ["config.core.description.control_the_wild_boar_numbers_in_the_alamo_sea_hills.f936c6fa"] = "Controlează numărul de mistreți de pe dealurile Mării Alamo.",
    ["config.core.description.dive_and_recover_submerged_cargo_from_wrecks_across_the_coast.111d4dd0"] = "Scufundați-vă și recuperați încărcătura scufundată din epavele de pe coastă.",
    ["config.core.description.fish_at_coastal_spots_and_sell_your_catch.8a753499"] = "Pescuiește în zonele de coastă și vinde-ți captura.",
    ["config.core.description.harvest_one_high_quality_qualifying_deer_shot_discipline_matters.6c2ad1fd"] = "Recoltați o căprioară calificată de înaltă calitate. Disciplina de aruncare contează.",
    ["config.core.description.haul_cargo_across_san_andreas_depot_at_the_docks.bf3898e1"] = "Transportă marfă prin San Andreas. Depozit la docuri.",
    ["config.core.description.haul_heavy_industrial_cargo_and_fuel_tanker_trailers_across_san_.4d740459"] = "Transportă remorci pentru încărcături industriale grele și cisterne de combustibil pe rețelele de autostrăzi din San Andreas.",
    ["config.core.description.hunt_wildlife_under_licensed_contract_requires_firearm_and_hunti.7e61f6e0"] = "Vânează animale sălbatice în baza unui contract de licență. Necesită licențe pentru arme de foc și vânătoare.",
    ["config.core.description.load_parcel_crates_at_the_distribution_warehouse_and_make_door_t.f342ecc8"] = "Încărcați lăzile de colete la depozitul de distribuție și efectuați livrări din ușă în ușă.",
    ["config.core.description.manage_deer_population_in_paleto_forest.d03eb059"] = "Gestionați populația de căprioare din pădurea Paleto.",
    ["config.core.description.operate_public_transit_bus_routes_across_los_santos_and_transpor.57e8fce3"] = "Exploatează rutele de transport public cu autobuzul prin Los Santos și transportă pasageri.",
    ["config.core.description.operate_scheduled_public_bus_lines_across_los_santos_pick_up_wai.79f65435"] = "Administrează linii de autobuz publice programate în Los Santos. Preia pasagerii în așteptare din stațiile de autobuz, emite bilete și câștigă tarife pentru pasageri + bonusuri de tranzit.",
    ["config.core.description.pick_up_packages_and_deliver_them_on_foot.6e79922e"] = "Ridicați pachetele și livrați-le pe jos.",
    ["config.core.description.recover_submerged_cargo_electronics_and_artifacts_from_coastal_w.9515213e"] = "Recuperează încărcătura scufundată, electronicele și artefactele din epavele de coastă.",
    ["config.core.description.reduce_predator_numbers_in_the_sandy_shores_area.faba271c"] = "Reduceți numărul de prădători în zona Sandy Shores.",
    ["config.core.description.respond_to_service_mechanic_calls_and_repair_vehicles.3c238968"] = "Răspundeți la apelurile/apelurile mecanicilor de service și reparați vehiculele.",
    ["config.core.description.skill_for_breaking_into_vehicles_improves_success_rate_when_usin.a2887eb8"] = "Abilitatea de a pătrunde în vehicule. Îmbunătățește rata de succes atunci când utilizați un dispozitiv de blocare.",
    ["config.core.description.take_on_wildlife_management_contracts_across_blaine_county_requi.90d9f1b9"] = "Preluați contracte de gestionare a faunei sălbatice în comitatul Blaine. Necesită o licență valabilă pentru arme de foc și vânătoare.",
    ["config.core.help.choose_a_hunting_contract_travel_to_the_zone_track_and_harvest_w.c32b213a"] = "Alegeți un contract de vânătoare, călătoriți în zonă, urmăriți și recoltați fauna sălbatică. Necesită licențe pentru arme de foc și vânătoare.",
    ["config.core.help.drive_to_bins_pick_up_trash_e_dump_at_the_truck_rear_then_unload.90281167"] = "Conduceți la pubele, ridicați gunoiul (E), aruncați-l în partea din spate a camionului, apoi descărcați-l la depozit atunci când este plin.",
    ["config.core.help.drive_your_transit_bus_along_the_scheduled_route_stop_at_bus_sto.706c2e7f"] = "Condu autobuzul de transport public de-a lungul rutei programate, oprește la stațiile de autobuz [E] pentru a urca la bordul pasagerilor, a colecta tarifele și a reveni la depou pentru bonusul de rută.",
    ["config.core.help.fish_in_the_paleto_bay_area_near_billy_ray_then_sell_your_catch_.3805a419"] = "Pescuiește în zona Paleto Bay de lângă Billy Ray, apoi vinde-ți captura la orice magazin disponibil non-stop.",
    ["config.core.help.go_on_duty_to_accept_service_mechanic_calls_repair_vehicles_to_e.72329385"] = "Mergeți la datorie pentru a accepta /repara apelurile mecanicilor. Reparați vehicule pentru a câștiga bani.",
    ["config.core.help.go_to_the_depot_spawn_your_rig_pick_up_cargo_deliver_then_return.227f42e7"] = "Mergeți la depozit, depuneți-vă echipamentul, ridicați încărcătura, livrați, apoi returnați camionul. Utilizați /recuperați remorca dacă remorca se desprinde sau este distrusă.",
    ["config.core.help.pick_a_salvage_contract_dive_to_the_search_area_use_the_detector.001bbf05"] = "Alegeți un contract de salvare, scufundați-vă în zona de căutare, utilizați detectorul pentru a localiza încărcătura și reveniți la vânzare.",
    ["config.core.help.spawn_your_van_load_all_packages_at_the_warehouse_loading_dock_t.c25c22b4"] = "Încarcă-ți furgoneta, încarcă toate pachetele la docul de încărcare al depozitului, apoi livrează-le din ușă în ușă fără a te întoarce între opriri.",
